        painting.setInfoTitle(dto.getInfoTitle());
        painting.setInfoText(dto.getInfoText());
        painting.setExternalLink(dto.getExternalLink());

        Painting updated = paintingRepository.save(painting);
        return convertToDTO(updated);
    }

    @Transactional
