{"filePath": "c:\Users\Youmni Malha\Documents\Projects\questify\Api\src\main\java\com\questify\api\controller\TestVerificationController.java", "content": "package com.questify.api.controller;

import com.questify.api.annotations.AllowAuthenticated;
import com.questify.api.dto.response.ImageVerificationResponseDTO;
import com.questify.api.dto.response.PaintingDetailDTO;
import com.questify.api.model.User;
import com.questify.api.services.implementation.MuseumService;
import com.questify.api.services.implementation.RouteProgressService;
import lombok.RequiredArgsConstructor;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

/**
 * TEST CONTROLLER - Voor development zonder MinIO
 * Dit endpoint simuleert altijd een succesvolle match
 */
@RestController
@RequestMapping("/api/test")
@RequiredArgsConstructor
public class TestVerificationController {

    private final RouteProgressService progressService;
    private final MuseumService museumService;

    /**
     * Test endpoint: Simuleert succesvolle scan zonder afbeelding vergelijking
     * 
     * POST /api/test/verify/routes/{routeId}/paintings/{paintingId}
     */
    @AllowAuthenticated
    @PostMapping("/verify/routes/{routeId}/paintings/{paintingId}")
    public ResponseEntity<ImageVerificationResponseDTO> testVerifyPainting(
            @PathVariable Long routeId,
            @PathVariable Long paintingId,
            @AuthenticationPrincipal User user
    ) {
        try {
            // Advance to next stop (simuleert succesvolle scan)
            progressService.advanceToNextStop(user.getId(), routeId);

            // Return painting details
            PaintingDetailDTO details = museumService.getPaintingDetails(paintingId);

            return ResponseEntity.ok(
                    ImageVerificationResponseDTO.builder()
                            .isMatch(true)
                            .confidenceScore(0.95)
                            .message("TEST MODE: Automatically verified!")
                            .paintingDetails(details)
                            .build()
            );

        } catch (Exception e) {
            return ResponseEntity.ok(
                    ImageVerificationResponseDTO.builder()
                            .isMatch(false)
                            .confidenceScore(0.0)
                            .message("Test error: " + e.getMessage())
                            .build()
            );
        }
    }
}
"}

